if OUT.exists(): raise FileExistsError(OUT)
c=sqlite3.connect(OUT)
c.executescript('''CREATE TABLE run_source_index(case_id TEXT, condition TEXT, run_id TEXT PRIMARY KEY, cohort TEXT, patch_sha256 TEXT, after_sarif_sha256 TEXT, new_warning_count INTEGER, baseline_warning_count INTEGER, after_warning_count INTEGER, source_snapshot_status TEXT, provenance_source TEXT, raw_patch_status TEXT NOT NULL DEFAULT 'WITS_ONLY_NOT_EMBEDDED');
CREATE TABLE integration_status(item TEXT PRIMARY KEY, count INTEGER, evidence_status TEXT, notes TEXT);
CREATE TABLE unresolved_items(item TEXT PRIMARY KEY, coverage_status TEXT, notes TEXT);
CREATE TABLE metadata(key TEXT PRIMARY KEY, value TEXT);''')
